from PIL import Image, ImageFont, ImageDraw
import numpy as np
from scipy.ndimage import binary_fill_holes, binary_closing
im=np.array(Image.open('/tmp/txt_base.png').convert('L'))
ink=im<128
cols=ink.any(0)
spans=[]; instr=False; lastink=-999
for i,v in enumerate(cols):
    if v:
        if not instr: start=i; instr=True
        lastink=i
    else:
        if instr and i-lastink>=4:
            spans.append((start,lastink)); instr=False
if instr: spans.append((start,lastink))
def glyph(k):
    a,b=spans[k]; sub=ink[:,a:b+1]
    yy=np.where(sub.any(1))[0]; sub=sub[yy.min():yy.max()+1]
    return sub
def fontglyph(ch,path):
    f=ImageFont.truetype(path,400)
    img=Image.new('L',(600,600),0); d=ImageDraw.Draw(img)
    d.text((50,50),ch,fill=255,font=f)
    a=np.array(img)>128
    yy,xx=np.where(a)
    return a[yy.min():yy.max()+1,xx.min():xx.max()+1]
def iou(a,b):
    # resize b to a shape
    bi=Image.fromarray((b*255).astype('uint8')).resize((a.shape[1],a.shape[0]),Image.Resampling.LANCZOS)
    bb=np.array(bi)>128
    return (a&bb).sum()/max(1,(a|bb).sum())
fonts={'book':'/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','bold':'/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf','serif':'/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf','serifb':'/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf','mono':'/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf','monob':'/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf'}
tests={0:'ftlI1',1:'lI1',2:'a',3:'gq',5:'gq',6:'c',7:'O0oQ',8:'d',9:'3',11:'i',12:'z2',14:'c',15:'h',16:'4',17:'L',18:'L',19:'e',20:'n',21:'G6',22:'i',23:'N',24:'gq',25:'}'}
for k,cands in tests.items():
    g=glyph(k); g=binary_closing(binary_fill_holes(g),np.ones((3,3)))
    scores=[]
    for ch in cands:
        for fn,path in fonts.items():
            fg=binary_fill_holes(fontglyph(ch,path))
            scores.append((iou(g,fg),ch,fn))
    scores.sort(reverse=True)
    print(k,'shape',g.shape,'best',[(round(s,3),c,f) for s,c,f in scores[:4]])
